  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'Solve z² − 2z + 5 = 0.', 'z = (2 ± √(4 − 20))/2 = 1 ± 2i.', 12),
  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'What is an Argand diagram?', 'A diagram representing complex numbers as points, with the real part on the horizontal axis and the imaginary part on the vertical axis.', 13),
  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'How is z* shown on an Argand diagram?', 'As the reflection of z in the real axis.', 14),
