  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'Calculate (1 + i)⁸ using de Moivre.', '(√2)⁸(cos 2π + i sin 2π) = 16.', 26),
  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'How can de Moivre express cos 3θ in terms of cos θ?', 'Expand (cos θ + i sin θ)³ and take the real part: cos 3θ = 4cos³θ − 3cos θ.', 27),
  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'Express sin 3θ in terms of sin θ.', 'sin 3θ = 3 sin θ − 4 sin³θ.', 28),
  ('Further Mathematics', 'AQA', 'alevel', '1.1', 'Complex Numbers', 'What is z + 1/z if z = e^(iθ)?', '2 cos θ.', 29),
