  ('Further Mathematics', 'AQA', 'alevel', '1.3', 'Further Algebra & Functions', 'Why can''t you multiply both sides of an inequality by (x − 1)?', 'Its sign is unknown; multiply by (x − 1)² instead, or use a sign diagram.', 11),
  ('Further Mathematics', 'AQA', 'alevel', '1.3', 'Further Algebra & Functions', 'What is the equation of a parabola in standard form?', 'y² = 4ax, with focus (a, 0) and directrix x = −a.', 12),
