  ('Further Mathematics', 'AQA', 'alevel', '1.3', 'Further Algebra & Functions', 'What is the equation of a hyperbola centred at the origin?', 'x²/a² − y²/b² = 1, with asymptotes y = ±(b/a)x.', 14),
  ('Further Mathematics', 'AQA', 'alevel', '1.3', 'Further Algebra & Functions', 'What is a rectangular hyperbola?', 'xy = c², with the axes as asymptotes.', 15),
