  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'Find Σ (2r − 1) from r = 1 to n.', 'n(n + 1) − n = n².', 6),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'Find Σ r(r + 1) from r = 1 to n.', 'Σr² + Σr = n(n + 1)(n + 2)/3.', 7),
