  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the method of differences?', 'Writing each term as f(r) − f(r + 1) so that most terms cancel when summed.', 9),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'Use the method of differences to sum Σ 1/(r(r + 1)).', '1/(r(r + 1)) = 1/r − 1/(r + 1), so the sum from 1 to n is 1 − 1/(n + 1).', 10),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'Find Σ 1/(r(r + 2)) from r = 1 to n.', '½ Σ (1/r − 1/(r + 2)) = ½(3/2 − 1/(n + 1) − 1/(n + 2)).', 11),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is a telescoping series?', 'A series in which consecutive terms cancel, leaving only a few terms.', 12),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the sum to infinity of Σ 1/(r(r + 1))?', '1.', 13),
