  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is a Maclaurin series?', 'f(x) = f(0) + f''(0)x + f''''(0)x²/2! + f''''''(0)x³/3! + …', 16),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the Maclaurin series for eˣ?', '1 + x + x²/2! + x³/3! + …, valid for all x.', 17),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the Maclaurin series for sin x?', 'x − x³/3! + x⁵/5! − …, valid for all x.', 18),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the Maclaurin series for cos x?', '1 − x²/2! + x⁴/4! − …, valid for all x.', 19),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the Maclaurin series for ln(1 + x)?', 'x − x²/2 + x³/3 − …, valid for −1 < x ≤ 1.', 20),
  ('Further Mathematics', 'AQA', 'alevel', '1.4', 'Series', 'What is the Maclaurin series for (1 + x)ⁿ?', '1 + nx + n(n − 1)x²/2! + …, valid for |x| < 1 (non-integer n).', 21),
