  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'What is the volume of revolution about the x-axis?', 'V = π ∫ y² dx between the limits.', 19),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'What is the volume of revolution about the y-axis?', 'V = π ∫ x² dy between the y-limits.', 20),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'Find the volume when y = x from 0 to 3 is rotated about the x-axis.', 'π ∫₀³ x² dx = 9π (a cone).', 21),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'Find the volume when y = √x from 0 to 4 is rotated about the x-axis.', 'π ∫₀⁴ x dx = 8π.', 22),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'Find the volume when y = x² from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ x⁴ dx = π/5.', 23),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'How do you find the volume between two curves rotated about the x-axis?', 'V = π ∫ (y₁² − y₂²) dx, where y₁ is the outer curve.', 24),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'Why is it not π ∫ (y₁ − y₂)² dx?', 'The solid is a washer: the volume is the outer solid minus the inner solid.', 25),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'How do you rotate y = x² about the y-axis between y = 0 and y = 4?', 'x² = y, so V = π ∫₀⁴ y dy = 8π.', 26),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'What is the volume of a sphere derived by rotation?', 'Rotate x² + y² = r² about the x-axis: π ∫₋ᵣʳ (r² − x²) dx = (4/3)πr³.', 27),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'What is the volume of a cone derived by rotation?', 'Rotate y = (r/h)x from 0 to h: π ∫ (r²/h²)x² dx = (1/3)πr²h.', 28),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'How can volumes of revolution model real objects?', 'E.g. vases, bottles and bowls can be modelled by rotating curves.', 29),
  ('Further Mathematics', 'AQA', 'alevel', '1.5', 'Further Calculus', 'What assumption is made when modelling an object with a volume of revolution?', 'The object is perfectly symmetrical about its axis and the curve accurately describes its profile.', 30),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the vector equation of a line?', 'r = a + λb, where a is a point on the line and b is the direction vector.', 1),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the Cartesian equation of a line?', '(x − a₁)/b₁ = (y − a₂)/b₂ = (z − a₃)/b₃.', 2),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the scalar (dot) product?', 'a·b = a₁b₁ + a₂b₂ + a₃b₃ = |a||b| cos θ.', 3),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What does a·b = 0 mean?', 'The vectors are perpendicular.', 4),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the angle between two lines?', 'Use the dot product of their direction vectors: cos θ = (b₁·b₂)/(|b₁||b₂|).', 5),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the vector equation of a plane?', 'r = a + λb + μc, or r·n = a·n.', 6),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the Cartesian equation of a plane?', 'n₁x + n₂y + n₃z = d, where n is the normal.', 7),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is a normal vector to a plane?', 'A vector perpendicular to the plane.', 8),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the angle between a line and a plane?', 'Find the angle between the direction and the normal, then subtract from 90°.', 9),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the angle between two planes?', 'Find the angle between their normals.', 10),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find where a line meets a plane?', 'Substitute the line''s parametric form into the plane equation and solve for λ.', 11),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you tell if two lines are skew?', 'They are not parallel and don''t intersect.', 12),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the intersection of two lines?', 'Set the vector equations equal and solve for the parameters, checking all three components.', 13),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the vector (cross) product?', 'a × b, a vector perpendicular to both a and b with magnitude |a||b| sin θ.', 14),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you calculate a × b?', '(a₂b₃ − a₃b₂, a₃b₁ − a₁b₃, a₁b₂ − a₂b₁).', 15),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the normal to a plane containing vectors b and c?', 'Calculate b × c.', 16),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the perpendicular distance from a point to a plane?', '|ax₀ + by₀ + cz₀ − d|/√(a² + b² + c²).', 17),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the shortest distance between skew lines?', '|(a₂ − a₁)·n|/|n|, where n = b₁ × b₂.', 18),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the shortest distance from a point to a line?', 'Find the foot of the perpendicular (where (p − r)·b = 0), then find the distance.', 19),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the area of a triangle using vectors?', '½|AB × AC|.', 20),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the volume of a parallelepiped?', '|a·(b × c)| (the scalar triple product).', 21),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the line of intersection of two planes?', 'It has direction n₁ × n₂; find a point by solving the equations with one variable fixed.', 22),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you find the reflection of a point in a plane?', 'Find the foot of the perpendicular, then go the same distance beyond it.', 23),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'When are two planes parallel?', 'When their normals are parallel.', 24),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What does r·n = d mean geometrically?', 'All points whose component along n is d/|n| from the origin.', 25),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'Find the angle between (1, 2, 2) and (2, −1, 2).', 'Dot product = 2 − 2 + 4 = 4; |a| = |b| = 3; cos θ = 4/9, θ ≈ 63.6°.', 26),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'How do you check a point lies on a line?', 'Find a λ that satisfies all three components.', 27),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is a unit normal?', 'A normal vector divided by its magnitude.', 28),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'Find the Cartesian equation of the plane with normal (2, −1, 3) through (1, 1, 1).', '2x − y + 3z = 4.', 29),
  ('Further Mathematics', 'AQA', 'alevel', '1.6', 'Further Vectors', 'What is the scalar product of a vector with itself?', 'a·a = |a|².', 30),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What are polar coordinates?', 'Coordinates (r, θ), where r is the distance from the pole and θ is the angle from the initial line.', 1),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you convert polar to Cartesian?', 'x = r cos θ, y = r sin θ.', 2),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you convert Cartesian to polar?', 'r² = x² + y², tan θ = y/x (taking care with the quadrant).', 3),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the polar equation r = a?', 'A circle with centre the pole and radius a.', 4),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the polar equation θ = α?', 'A half-line from the pole at angle α.', 5),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = aθ?', 'A spiral (Archimedean spiral).', 6),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = a(1 + cos θ)?', 'A cardioid.', 7),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = a cos 2θ?', 'A four-petalled rose curve.', 8),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = 2a cos θ?', 'A circle through the pole, with centre (a, 0) and radius a.', 9),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the area enclosed by a polar curve?', 'A = ½ ∫ r² dθ between the limits.', 10),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Find the area enclosed by r = 2 for 0 ≤ θ ≤ 2π.', '½ ∫ 4 dθ = 4π.', 11),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Find the area of the cardioid r = 1 + cos θ.', '½ ∫₀^(2π) (1 + cos θ)² dθ = 3π/2.', 12),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you find where two polar curves intersect?', 'Set the r-values equal and solve for θ, also checking the pole.', 13),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you find a tangent parallel to the initial line?', 'Set dy/dθ = 0, where y = r sin θ.', 14),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you find a tangent perpendicular to the initial line?', 'Set dx/dθ = 0, where x = r cos θ.', 15),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Convert r = 4 sin θ to Cartesian form.', 'r² = 4r sin θ, so x² + y² = 4y (a circle centred at (0, 2)).', 16),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Convert x² + y² = 9 to polar form.', 'r = 3.', 17),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Convert y = x to polar form.', 'θ = π/4 (and θ = −3π/4 for negative r).', 18),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Why is r usually taken as non-negative?', 'By convention r ≥ 0; values of θ that give negative r are excluded from the sketch.', 19),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What does a cardioid look like?', 'A heart shape with a cusp at the pole.', 20),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How many petals does r = cos 3θ have?', '3.', 21),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How many petals does r = cos 2θ have?', '4.', 22),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the area of one petal of r = cos 2θ?', '½ ∫ from −π/4 to π/4 of cos²2θ dθ = π/8.', 23),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What identity helps integrate r² = cos²θ?', 'cos²θ = (1 + cos 2θ)/2.', 24),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you sketch a polar curve?', 'Tabulate r for key θ values, note symmetry, and find where r = 0 and r is maximum.', 25),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What does symmetry about the initial line mean for r = f(θ)?', 'f(−θ) = f(θ), e.g. curves involving only cos θ.', 26),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'How do you find the area between two polar curves?', 'Subtract the areas: ½ ∫ (r₁² − r₂²) dθ over the appropriate range.', 27),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the maximum r of r = 3 + 2 cos θ?', '5, when θ = 0.', 28),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'Does r = 3 + 2 cos θ pass through the pole?', 'No, since r ≥ 1 for all θ (a dimpled limaçon).', 29),
  ('Further Mathematics', 'AQA', 'alevel', '1.7', 'Polar Coordinates', 'What is the pole?', 'The origin in polar coordinates.', 30),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the definition of sinh x?', 'sinh x = (eˣ − e^(−x))/2.', 1),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the definition of cosh x?', 'cosh x = (eˣ + e^(−x))/2.', 2),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the definition of tanh x?', 'tanh x = sinh x/cosh x = (eˣ − e^(−x))/(eˣ + e^(−x)).', 3),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the key hyperbolic identity?', 'cosh²x − sinh²x = 1.', 4),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the range of cosh x?', 'cosh x ≥ 1.', 5),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the range of tanh x?', '−1 < tanh x < 1.', 6),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What does the graph of y = cosh x look like?', 'A U-shape (catenary) with minimum (0, 1), symmetric about the y-axis.', 7),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What does the graph of y = sinh x look like?', 'An S-shape through the origin, increasing, and odd.', 8),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of sinh x?', 'cosh x.', 9),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of cosh x?', 'sinh x.', 10),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of tanh x?', 'sech²x.', 11),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is Osborn''s rule?', 'To convert a trig identity to a hyperbolic one, replace cos with cosh and sin with sinh, but change the sign of any product of two sines.', 12),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is sinh 2x?', '2 sinh x cosh x.', 13),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is cosh 2x?', 'cosh²x + sinh²x = 2cosh²x − 1 = 1 + 2sinh²x.', 14),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is arsinh x in logarithmic form?', 'ln(x + √(x² + 1)).', 15),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is arcosh x in logarithmic form?', 'ln(x + √(x² − 1)), for x ≥ 1.', 16),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is artanh x in logarithmic form?', '½ ln((1 + x)/(1 − x)), for |x| < 1.', 17),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of arsinh x?', '1/√(x² + 1).', 18),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of arcosh x?', '1/√(x² − 1).', 19),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of artanh x?', '1/(1 − x²).', 20),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'Solve cosh x = 2.', 'x = ±ln(2 + √3).', 21),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'Solve sinh x = 3/4.', 'x = ln(3/4 + 5/4) = ln 2.', 22),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'Solve 3 sinh x + cosh x = 3.', 'In exponentials: 3(eˣ − e^(−x))/2 + (eˣ + e^(−x))/2 = 3 → 2eˣ − e^(−x) = 3 → 2e^(2x) − 3eˣ − 1 = 0, eˣ = (3 + √17)/4, x = ln((3 + √17)/4).', 23),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is ∫ sinh x dx?', 'cosh x + c.', 24),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is ∫ cosh x dx?', 'sinh x + c.', 25),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is ∫ tanh x dx?', 'ln cosh x + c.', 26),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is a catenary?', 'The shape of a hanging chain, described by y = a cosh(x/a).', 27),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'Is cosh x even or odd?', 'Even.', 28),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'Is sinh x even or odd?', 'Odd.', 29),
  ('Further Mathematics', 'AQA', 'alevel', '1.8', 'Hyperbolic Functions', 'What is sech x?', '1/cosh x.', 30),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is an integrating factor?', 'For dy/dx + P(x)y = Q(x), the integrating factor is e^(∫P dx).', 1),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'How do you solve dy/dx + P(x)y = Q(x)?', 'Multiply by the integrating factor I: d(Iy)/dx = IQ, then integrate.', 2),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'Solve dy/dx + 2y = e^(−x).', 'IF = e^(2x): (ye^(2x))'' = eˣ, so y = e^(−x) + Ce^(−2x).', 3),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'Solve x dy/dx + y = x².', '(xy)'' = x², so xy = x³/3 + C, y = x²/3 + C/x.', 4),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is a second-order linear differential equation with constant coefficients?', 'a d²y/dx² + b dy/dx + cy = f(x).', 5),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the auxiliary equation?', 'am² + bm + c = 0.', 6),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the complementary function if the auxiliary equation has distinct real roots α, β?', 'y = Ae^(αx) + Be^(βx).', 7),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the complementary function for a repeated root α?', 'y = (A + Bx)e^(αx).', 8),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the complementary function for complex roots p ± qi?', 'y = e^(px)(A cos qx + B sin qx).', 9),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the general solution of a non-homogeneous second-order ODE?', 'Complementary function + particular integral.', 10),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is a particular integral?', 'Any solution of the full equation, found by trying a function similar to f(x).', 11),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What trial function is used for f(x) = ke^(λx)?', 'Ae^(λx) (or Axe^(λx) if λ is a root of the auxiliary equation).', 12),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What trial function is used for f(x) = polynomial of degree n?', 'A general polynomial of degree n.', 13),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What trial function is used for f(x) = k cos ωx?', 'A cos ωx + B sin ωx.', 14),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What happens if the trial function is part of the complementary function?', 'Multiply the trial by x (or x² for a repeated root).', 15),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'Solve y'''' − 5y'' + 6y = 0.', 'm² − 5m + 6 = 0, m = 2, 3: y = Ae^(2x) + Be^(3x).', 16),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'Solve y'''' + 4y = 0.', 'm = ±2i: y = A cos 2x + B sin 2x.', 17),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'Solve y'''' + 2y'' + y = 0.', 'm = −1 (repeated): y = (A + Bx)e^(−x).', 18),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is simple harmonic motion as a differential equation?', 'd²x/dt² = −ω²x.', 19),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the general solution of d²x/dt² = −ω²x?', 'x = A cos ωt + B sin ωt.', 20),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is damped harmonic motion?', 'd²x/dt² + k dx/dt + ω²x = 0, where the damping term reduces the amplitude.', 21),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is heavy damping?', 'The auxiliary equation has two distinct real (negative) roots; the system returns to equilibrium slowly without oscillating.', 22),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is critical damping?', 'The auxiliary equation has a repeated root; the system returns to equilibrium fastest without oscillating.', 23),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is light damping?', 'The auxiliary equation has complex roots; the system oscillates with decreasing amplitude.', 24),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is forced oscillation?', 'An oscillating system with an external driving force: x'''' + kx'' + ω²x = f(t).', 25),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is resonance in DEs?', 'When the driving frequency equals the natural frequency, amplitude grows (the particular integral includes t).', 26),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'How is population growth with limits modelled?', 'dP/dt = kP(1 − P/K), the logistic equation.', 27),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'How is predator–prey interaction modelled?', 'Using coupled first-order differential equations for each population.', 28),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What is the general strategy for coupled DEs?', 'Eliminate one variable by differentiating to give a second-order DE in the other.', 29),
  ('Further Mathematics', 'AQA', 'alevel', '1.9', 'Differential Equations', 'What does the steady state of a model mean?', 'The long-term behaviour, e.g. when derivatives are zero.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Further Mathematics' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
